<?php
namespace Tests\Feature;use App\Models\Quartier;use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Facades\Http;use Tests\TestCase;
class NominatimTest extends TestCase{use RefreshDatabase;public function test_address_is_geocoded_when_creating_signalement():void{$q=Quartier::create(['nom'=>'Bardo','ville'=>'Tunis','latitude'=>36.809,'longitude'=>10.140,'actif'=>true]);$u=User::factory()->create(['quartier_id'=>$q->id]);Http::fake(['nominatim.openstreetmap.org/*'=>Http::response([['lat'=>'36.8090','lon'=>'10.1400','display_name'=>'Le Bardo, Tunis, Tunisia']])]);$this->actingAs($u)->post('/signalements',['quartier_id'=>$q->id,'titre'=>'Coupure','description'=>'Test','adresse'=>'Bardo'])->assertSessionHas('success');$this->assertDatabaseHas('signalements',['user_id'=>$u->id,'latitude'=>36.8090,'longitude'=>10.1400]);}public function test_signalement_is_saved_when_geocoding_fails():void{$q=Quartier::create(['nom'=>'Bardo','ville'=>'Tunis','latitude'=>36.809,'longitude'=>10.140,'actif'=>true]);$u=User::factory()->create(['quartier_id'=>$q->id]);Http::fake(['*'=>Http::response([],500)]);$this->actingAs($u)->post('/signalements',['quartier_id'=>$q->id,'titre'=>'Coupure','description'=>'Test','adresse'=>'Bardo'])->assertSessionHas('success');$this->assertDatabaseHas('signalements',['user_id'=>$u->id,'titre'=>'Coupure']);}}
